commonware-math = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-codec = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-formatting = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-utils = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-coding = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-macros = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-runtime = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-storage = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-deployer = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-parallel = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-resolver = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-broadcast = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
commonware-consensus = { git = "https://github.com/commonwarexyz/monorepo", rev = "92036f4beefedc9817f0954d98fb99e0b52431cb" }
