# Exoware
exoware-sdk = { git = "https://github.com/exowarexyz/monorepo", rev = "5da4686d2b3de2eae1f7a04d714b0d3087387929" }
exoware-server = { git = "https://github.com/exowarexyz/monorepo", rev = "5da4686d2b3de2eae1f7a04d714b0d3087387929" }
